    const s = line.trim();
    const target = "CODEFORCES";
    if (s.length < 10) {
        console.log("NO");
        rl.close();
        return;
    }
    let found = false;
    for (let i = 0; i <= 10; i++) {
        const prefix = s.substring(0, i);
        const suffix = s.substring(s.length - (10 - i));
        if (prefix + suffix === target) {
            found = true;
            break;
        }
    }
    console.log(found ? "YES" : "NO");
